          <span>Gate</span>
          <span>Checks</span>
          <span>Reason</span>
          <span>Screenshots</span>
          <span />
        </div>
        {sorted.map(lane => <LaneResult key={lane.worker} lane={lane} context={context} />)}
      </div>
    </NodeSection>
  )
}

